<?php
declare(strict_types=1);
session_name('darbar_admin');session_start();require dirname(__DIR__).'/includes/db.php';
register_shutdown_function(static function():void{if(!empty($_SESSION['admin_id']))echo '<script src="admin.js"></script>';});
function ae($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function setting(string $key,string $fallback=''):string{global $pdo;if(!$pdo)return $fallback;$q=$pdo->prepare('SELECT setting_value FROM settings WHERE setting_key=?');$q->execute([$key]);return (string)($q->fetchColumn()?:$fallback);}
function token():string{$_SESSION['admin_csrf']??=bin2hex(random_bytes(32));return $_SESSION['admin_csrf'];}
function check_token():void{$sessionToken=(string)($_SESSION['admin_csrf']??'');$postedToken=(string)($_POST['csrf']??'');if($sessionToken===''||$postedToken===''||!hash_equals($sessionToken,$postedToken))throw new RuntimeException('Your session token expired. Refresh the page and try again.');}
function go(string $s,string $m){$_SESSION['flash']=$m;header('Location:?section='.$s);exit;}
function image_upload(string $field,string $folder,string $old=''):string{if(empty($_FILES[$field]['tmp_name']))return $old;if($_FILES[$field]['size']>6291456)throw new RuntimeException('Image must be under 6 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES[$field]['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??'';if(!$ext)throw new RuntimeException('Only JPG, PNG and WebP are allowed.');$rel='uploads/'.$folder.'/'.bin2hex(random_bytes(10)).'.'.$ext;$dest=dirname(__DIR__).'/'.$rel;if(!is_dir(dirname($dest)))mkdir(dirname($dest),0775,true);if(!move_uploaded_file($_FILES[$field]['tmp_name'],$dest))throw new RuntimeException('Upload failed.');return $rel;}
if(isset($_GET['logout'])){session_destroy();header('Location:index.php');exit;}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['login'])){$a=false;if($pdo){$q=$pdo->prepare('SELECT * FROM admins WHERE email=? AND is_active=1');$q->execute([$_POST['email']]);$a=$q->fetch();}if($a&&password_verify($_POST['password'],$a['password'])){$_SESSION['admin_id']=$a['id'];$_SESSION['admin_name']=$a['name'];$_SESSION['last_seen']=time();session_regenerate_id(true);header('Location:index.php');exit;}$error='Email or password was not recognised.';}
if(empty($_SESSION['admin_id'])):?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="../assets/css/style.css"><link rel="stylesheet" href="style.css"><title>Admin · Darbar Sweets</title></head><body class="admin-login"><form method="post" class="login-card"><img src="../uploads/logo/darbar-sweets-logo.png"><h1>Welcome back</h1><?php if($error):?><p class="alert"><?=ae($error)?></p><?php endif?><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" required></label><button class="btn btn-block" name="login">Sign in</button></form></body></html><?php exit;endif;
if(time()-($_SESSION['last_seen']??0)>1800){session_destroy();header('Location:index.php');exit;}$_SESSION['last_seen']=time();
$section=preg_replace('/[^a-z-]/','',$_GET['section']??'dashboard');$labels=['dashboard'=>'Dashboard','products'=>'Products','categories'=>'Categories','orders'=>'Orders','customers'=>'Customers','payments'=>'Payments','coupons'=>'Coupons','banners'=>'Banners','pages'=>'Pages','settings'=>'Brand Settings'];$title=$labels[$section]??'Dashboard';$editId=(int)($_GET['edit']??0);
if($pdo&&$_SERVER['REQUEST_METHOD']==='POST'&&!isset($_POST['login'])){try{check_token();$a=$_POST['action']??'';
 if($a==='banner_save'){$id=(int)$_POST['id'];$img=image_upload('image','banners',$_POST['old_image']);$d=[trim($_POST['title']),trim($_POST['subtitle']),$img,trim($_POST['button_text']),trim($_POST['button_link']),'home_slider',(int)$_POST['sort_order'],isset($_POST['is_active'])?1:0];if($id){$d[]=$id;$pdo->prepare('UPDATE banners SET title=?,subtitle=?,image=?,button_text=?,button_link=?,placement=?,sort_order=?,is_active=? WHERE id=?')->execute($d);}else{$pdo->prepare('INSERT INTO banners(title,subtitle,image,button_text,button_link,placement,sort_order,is_active) VALUES(?,?,?,?,?,?,?,?)')->execute($d);}go('banners','Banner saved and published.');}
 if($a==='banner_delete'){$pdo->prepare('DELETE FROM banners WHERE id=?')->execute([(int)$_POST['id']]);go('banners','Banner deleted.');}
 if($a==='product_save'){$id=(int)$_POST['id'];$img=image_upload('image','products',(string)($_POST['old_image']??''));if(!$id&&$img==='')throw new RuntimeException('Please upload a product image.');$sku=trim((string)($_POST['sku']??''));$sku=$sku===''?null:$sku;$slug=trim((string)$_POST['slug']);if(!preg_match('/^[a-z0-9]+(?:-[a-z0-9]+)*$/',$slug))throw new RuntimeException('Slug may contain lowercase letters, numbers and hyphens only.');$d=[(int)$_POST['category_id'],trim($_POST['name']),$slug,$sku,trim($_POST['short_description']),(float)$_POST['price'],($_POST['compare_price']===''?null:(float)$_POST['compare_price']),(int)$_POST['stock'],$img,isset($_POST['is_featured'])?1:0,isset($_POST['is_active'])?1:0];if($id){$d[]=$id;$pdo->prepare('UPDATE products SET category_id=?,name=?,slug=?,sku=?,short_description=?,price=?,compare_price=?,stock=?,image=?,is_featured=?,is_active=? WHERE id=?')->execute($d);}else{$pdo->prepare('INSERT INTO products(category_id,name,slug,sku,short_description,price,compare_price,stock,image,is_featured,is_active) VALUES(?,?,?,?,?,?,?,?,?,?,?)')->execute($d);}go('products','Product saved on live shop.');}
 if($a==='category_save'){$id=(int)$_POST['id'];$img=image_upload('image','categories',$_POST['old_image']);$d=[trim($_POST['name']),trim($_POST['slug']),$img,trim($_POST['description']),(int)$_POST['sort_order'],isset($_POST['is_featured'])?1:0,isset($_POST['is_active'])?1:0];if($id){$d[]=$id;$pdo->prepare('UPDATE categories SET name=?,slug=?,image=?,description=?,sort_order=?,is_featured=?,is_active=? WHERE id=?')->execute($d);}else{$pdo->prepare('INSERT INTO categories(name,slug,image,description,sort_order,is_featured,is_active) VALUES(?,?,?,?,?,?,?)')->execute($d);}go('categories','Category saved.');}
 if($a==='order_status'){$pdo->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);go('orders','Order status updated.');}
 if($a==='customer_toggle'){$pdo->prepare('UPDATE users SET is_blocked=1-is_blocked WHERE id=?')->execute([(int)$_POST['id']]);go('customers','Customer access updated.');}
 if($a==='coupon_save'){
  $expiry=$_POST['expires_at']===''?null:$_POST['expires_at'];
  $limit=$_POST['usage_limit']===''?null:(int)$_POST['usage_limit'];
  $pdo->prepare('INSERT INTO coupons(code,type,value,min_order,usage_limit,expires_at,is_active) VALUES(?,?,?,?,?,?,1)')->execute([strtoupper(trim($_POST['code'])),$_POST['type'],(float)$_POST['value'],(float)$_POST['min_order'],$limit,$expiry]);
  go('coupons','Coupon saved.');
 }
 if($a==='footer_settings_save'){$keys=['footer_about','footer_location','footer_hours','footer_phone','footer_copyright','footer_facebook','footer_instagram','footer_whatsapp'];foreach($keys as $k){$pdo->prepare('INSERT INTO settings(setting_key,setting_value,setting_group) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$k,trim((string)($_POST[$k]??'')),'footer']);}foreach(['payment_visa','payment_mastercard','payment_jazzcash','payment_easypaisa'] as $k){$pdo->prepare('INSERT INTO settings(setting_key,setting_value,setting_group) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$k,isset($_POST[$k])?'1':'0','footer']);}go('settings','Footer details published to website.');}
 if($a==='settings_save'){foreach(['site_name','announcement','hero_heading','hero_subtitle','color_primary','color_secondary','contact_phone','contact_email','footer_about','seo_site_description','seo_keywords'] as $k){$pdo->prepare('INSERT INTO settings(setting_key,setting_value,setting_group) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$k,trim((string)$_POST[$k]),'branding']);}$logo=image_upload('logo','logo',$_POST['old_logo']);$pdo->prepare("INSERT INTO settings(setting_key,setting_value,setting_group) VALUES('logo',?,'branding') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)")->execute([$logo]);go('settings','Settings applied to website.');}
 if($a==='about_save'){$keys=['about_eyebrow','about_heading','about_para1','about_para2','about_stat1_num','about_stat1_label','about_stat2_num','about_stat2_label','about_stat3_num','about_stat3_label','about_values_heading','about_value1_title','about_value1_text','about_value2_title','about_value2_text','about_value3_title','about_value3_text'];foreach($keys as $k){$pdo->prepare('INSERT INTO settings(setting_key,setting_value,setting_group) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$k,trim((string)($_POST[$k]??'')),'pages']);}$aboutImage=image_upload('about_image','pages',$_POST['old_about_image']);$pdo->prepare("INSERT INTO settings(setting_key,setting_value,setting_group) VALUES('about_image',?,'pages') ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)")->execute([$aboutImage]);go('pages','Our Story page published.');}
 if($a==='contact_save'){$keys=['contact_hero_text','contact_store_title','contact_address','contact_phone','contact_whatsapp','contact_hours','contact_map_text'];foreach($keys as $k){$pdo->prepare('INSERT INTO settings(setting_key,setting_value,setting_group) VALUES(?,?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)')->execute([$k,trim((string)($_POST[$k]??'')),'pages']);}go('pages','Contact page published.');}
}catch(PDOException $e){$error=$e->getCode()==='23000'?'That slug or SKU already exists. Please use a unique value.':'Database could not save this change. Please verify the entered values and try again.';}catch(Throwable $e){$error=$e->getMessage();}}
$flash=$_SESSION['flash']??'';unset($_SESSION['flash']);
$stats=['orders'=>0,'revenue'=>0,'customers'=>0,'pending'=>0,'products'=>0,'low_stock'=>0,'average'=>0,'paid'=>0];
if($pdo){
 $stats['orders']=$pdo->query('SELECT COUNT(*) FROM orders')->fetchColumn();
 $stats['revenue']=$pdo->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE status!='cancelled'")->fetchColumn();
 $stats['customers']=$pdo->query('SELECT COUNT(*) FROM users')->fetchColumn();
 $stats['pending']=$pdo->query("SELECT COUNT(*) FROM orders WHERE status='pending'")->fetchColumn();
 $stats['products']=$pdo->query('SELECT COUNT(*) FROM products WHERE is_active=1')->fetchColumn();
 $stats['low_stock']=$pdo->query('SELECT COUNT(*) FROM products WHERE is_active=1 AND stock<=10')->fetchColumn();
 $stats['average']=$pdo->query("SELECT COALESCE(AVG(total),0) FROM orders WHERE status!='cancelled'")->fetchColumn();
 $stats['paid']=$pdo->query("SELECT COALESCE(SUM(amount),0) FROM payments WHERE status='paid'")->fetchColumn();
}
